#nullable enable
using Alba;
using HourBooking.Contracts;
using HourBooking.Slices.Booking;
using Shouldly;
using Xunit;

namespace HourBooking.IntegrationTests.Slices.Booking;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation — which is the only reason these
/// tests mean anything. Pattern: command. Status: in-progress. LIVE: this slice is claimed, so every
/// test here must pass.
///
/// Third slice on the Timesheet stream, so the GIVENs append straight to it — history, not a sequence
/// of requests to replay. WHEN is a bodiless DELETE: every field the model gives RemoveBooking is
/// carried by the route.
/// </summary>
public sealed class RemoveBookingTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static string Timesheet => RemoveBookingState.StreamKey(SeedData.EmployeeId, SeedData.Month);
    private static string MonthClosure => MonthGate.StreamKey(SeedData.EmployeeId, SeedData.Month);

    private static BookingMonthStarted MonthOpened =>
        new(SeedData.EmployeeId, SeedData.EmployeeName, SeedData.Month, SeedData.SeededAt);

    private static readonly Guid Booking = Guid.Parse("dddd0000-0000-0000-0000-00000000000d");

    private static HoursBooked Booked(decimal hours, Guid? id = null, Guid? projectId = null) =>
        new(id ?? Booking, SeedData.EmployeeId, SeedData.Month, projectId ?? SeedData.ProjectId,
            SeedData.WorkingDay, hours, "as booked", SeedData.SeededAt);

    private async Task<IScenarioResult> Remove(Guid? bookingId = null)
    {
        var id = bookingId ?? Booking;
        var (_, result) = await WhenPosting(x =>
        {
            x.Delete.Url($"/timesheet/{SeedData.EmployeeId}/{SeedData.Month}/bookings/{id}");
            // Each test asserts its own status; Alba would otherwise insist on 200.
            x.IgnoreStatusCode();
        });
        return result;
    }

    // an employee can remove their own booking while the month is open
    //   GIVEN HoursBooked
    //   WHEN  RemoveBooking
    //   THEN  BookingRemoved
    [Fact]
    public async Task AnEmployeeCanRemoveTheirOwnBookingWhileTheMonthIsOpen()
    {
        await Given(MonthClosure, MonthOpened);
        await Given(Timesheet, Booked(7.5m));

        var result = await Remove();

        result.Context.Response.StatusCode.ShouldBe(204);
        var removed = (await EventsFor(Timesheet)).OfType<BookingRemoved>().ShouldHaveSingleItem();
        removed.BookingId.ShouldBe(Booking);
        removed.EmployeeId.ShouldBe(SeedData.EmployeeId);
        removed.Month.ShouldBe(SeedData.Month);

        // "their own" is enforced by the stream key, not by a rule: the booking of another employee is
        // in another stream, and this route can only reach this one.
        (await EventsFor(RemoveBookingState.StreamKey(SeedData.OtherEmployeeId, SeedData.Month)))
            .ShouldBeEmpty();
    }

    // removal is the only way to take a day+project back to nothing
    //   GIVEN HoursBooked, HoursCorrected
    //   WHEN  RemoveBooking
    //   THEN  BookingRemoved
    [Fact]
    public async Task RemovalIsTheOnlyWayToTakeADayProjectBackTo()
    {
        await Given(MonthClosure, MonthOpened);
        await Given(Timesheet,
            Booked(6m),
            new HoursCorrected(Booking, SeedData.EmployeeId, SeedData.Month, 8m, null, SeedData.SeededAt));

        var result = await Remove();

        result.Context.Response.StatusCode.ShouldBe(204);
        (await EventsFor(Timesheet)).OfType<BookingRemoved>().ShouldHaveSingleItem();

        // "back to nothing" is the assertion worth making, and it is two-sided. The line is gone from
        // the read model — the projection is inline, so it is already gone as the request returns...
        var sheet = await Host.Scenario(x =>
            x.Get.Url($"/timesheet/{SeedData.EmployeeId}/{SeedData.Month}"));
        var body = await sheet.ReadAsTextAsync();
        body.ShouldNotContain(Booking.ToString());
        body.ShouldContain("\"lines\": []", Case.Insensitive);

        // ...and the day+project is genuinely free again, which only booking it proves. A correction to
        // 0 is refused by correct-hours, so this is the ONLY route back to nothing — and it shows
        // book-hours' AlreadyBookedUseCorrection no longer fires for that day+project.
        var (_, rebooked) = await WhenPosting(x =>
        {
            x.Post
                .Json(new BookHours(Guid.NewGuid(), SeedData.EmployeeId, SeedData.Month,
                    SeedData.ProjectId, SeedData.WorkingDay, 4m, null))
                .ToUrl($"/timesheet/{SeedData.EmployeeId}/{SeedData.Month}/bookings");
            x.IgnoreStatusCode();
        });
        rebooked.Context.Response.StatusCode.ShouldBe(204);
    }

    // a booking already removed cannot be removed again
    //   GIVEN BookingRemoved
    //   WHEN  RemoveBooking
    //   THEN  error: BookingNotFound
    [Fact]
    public async Task ABookingAlreadyRemovedCannotBeRemovedAgain()
    {
        await Given(MonthClosure, MonthOpened);
        // The GWT names BookingRemoved as the decisive prior event; HoursBooked has to precede it,
        // because a booking must have existed to be removed. Both are history here.
        await Given(Timesheet,
            Booked(6m),
            new BookingRemoved(Booking, SeedData.EmployeeId, SeedData.Month, SeedData.SeededAt));

        var result = await Remove();

        result.Context.Response.StatusCode.ShouldBe(400);
        (await result.ReadAsTextAsync()).ShouldContain("BookingNotFound");

        // Not idempotent on purpose: the one BookingRemoved in the stream is the seeded one.
        (await EventsFor(Timesheet)).OfType<BookingRemoved>().ShouldHaveSingleItem()
            .RemovedAt.ShouldBe(SeedData.SeededAt);

        // The same refusal for an id the stream has never seen — indistinguishable from the stream's
        // point of view, and deliberately given the same name.
        var unknown = await Remove(Guid.Parse("eeee0000-0000-0000-0000-00000000000e"));
        unknown.Context.Response.StatusCode.ShouldBe(400);
        (await unknown.ReadAsTextAsync()).ShouldContain("BookingNotFound");
    }

    // a closed month cannot be edited — closed is closed
    //   GIVEN MonthClosed
    //   WHEN  RemoveBooking
    //   THEN  error: MonthIsClosed
    [Fact]
    public async Task AClosedMonthCannotBeEditedClosedIsClosed()
    {
        await Given(MonthClosure, MonthOpened,
            new MonthClosed(SeedData.EmployeeId, SeedData.Month, SeedData.AdminId, null, SeedData.SeededAt));
        await Given(Timesheet, Booked(6m));

        var result = await Remove();

        result.Context.Response.StatusCode.ShouldBe(400);
        (await result.ReadAsTextAsync()).ShouldContain("MonthIsClosed");

        // The booking is untouched: the month gate is read before the Timesheet stream is even fetched,
        // so nothing is persisted. Asserting the standing booking survives is what makes this a rule
        // about the month rather than about the booking.
        (await EventsFor(Timesheet)).OfType<BookingRemoved>().ShouldBeEmpty();
        (await EventsFor(Timesheet)).OfType<HoursBooked>().ShouldHaveSingleItem();
    }
}
